using Microsoft.EntityFrameworkCore;
using Nafadh_Backend.Models;

namespace Nafadh_Backend.Repositories
{
    public class BadgeRepository : IBadgeRepository
    {
        private readonly Nafadhcontext _context;

        public BadgeRepository(Nafadhcontext context)
        {
            _context = context;
        }

        public async Task<List<NFD_Badge>> GetAllBadgesAsync()
        {
            return await _context.NFD_Badges.ToListAsync();
        }

        public async Task<NFD_Badge?> GetBadgeByIdAsync(int badgeId)
        {
            return await _context.NFD_Badges.FindAsync(badgeId);
        }

        public async Task<List<NFD_TraineeBadge>> GetTraineeBadgesAsync(int traineeId)
        {
            return await _context.NFD_TraineeBadges
                .Include(tb => tb.Badge)
                .Where(tb => tb.TraineeId == traineeId)
                .ToListAsync();
        }

        public async Task<bool> HasBadgeAsync(int traineeId, int badgeId)
        {
            return await _context.NFD_TraineeBadges
                .AnyAsync(tb => tb.TraineeId == traineeId && tb.BadgeId == badgeId);
        }

        public async Task GrantBadgeAsync(int traineeId, int badgeId)
        {
            // Defensive re-check to avoid a duplicate grant race.
            var alreadyHas = await HasBadgeAsync(traineeId, badgeId);
            if (alreadyHas) return;

            await _context.NFD_TraineeBadges.AddAsync(new NFD_TraineeBadge
            {
                TraineeId = traineeId,
                BadgeId = badgeId,
                EarnedAt = DateTime.UtcNow
            });
            await _context.SaveChangesAsync();
        }
    }
}
